def solve(a, b, n, avg):
	if a[0] + b[0] == avg:
		b[0] = 0
	elif a[0] + b[1] == avg:
		b[1] = 0
	elif a[0] + b[0] + b[1] == avg:
		(b[0], b[1]) = (0, 0)
	elif a[0] != avg:
		flag = 1
		return -1
	if a[n - 1] + b[n - 1] == avg:
		b[n - 1] = 0
	elif a[n - 1] + b[n - 2] == avg:
		b[n - 2] = 0
	elif a[n - 1] + b[n - 1] + b[n - 2] == avg:
		(b[n - 1], b[n - 2]) = (0, 0)
	elif a[n - 1] != avg:
		flag = 1
		return -1
	for i in range(1, n - 1):
		a[i] += b[i - 1]
		b[i - 1] = 0
		if a[i] + b[i] == avg:
			b[i] = 0
		elif a[i] + b[i + 1] == avg:
			b[i + 1] = 0
		elif a[i] + b[i] + b[i + 1] == avg:
			(b[i], b[i + 1]) = (0, 0)
		elif a[i] != avg:
			return -1
	return avg
